W <- "/private/tmp/claude-501/-Users-pbtz-src-github-com-pedrobtz-zujson/9d8fe22c-5204-4620-9ce4-e537ce57bd23/scratchpad/hunt"
.libPaths(c(file.path(W,"lib"), .libPaths())); library(zujson)
t <- function(e) tryCatch(e, error=function(e) e, warning=function(w) w)
cat("== dup-key message with multibyte key cut at 64 bytes\n")
key <- paste0("a", strrep("é", 40))   # 81 bytes; byte 64 falls inside a 2-byte char
e <- t(json_parse(sprintf('[{"%s":1,"%s":2}]', key, key), data_frame=TRUE)); m <- conditionMessage(e)
cat(class(e)[1], "| validUTF8:", validUTF8(m), "| Encoding:", Encoding(m), "| nchar ok:", !is.na(tryCatch(nchar(m), error=function(e) NA)), "\n"); print(m)
key2 <- 'a\\"b%s%n'; e <- t(json_parse(sprintf('[{"%s":1,"%s":2}]', key2, key2), data_frame=TRUE)); print(conditionMessage(e))
key3 <- 'a\\u0000b'; e <- t(json_parse(sprintf('[{"%s":1,"%s":2}]', key3, key3), data_frame=TRUE)); print(conditionMessage(e))
cat("== file path messages\n")
d <- file.path(tempdir(), strrep("é", 100)); dir.create(d); f <- file.path(d, paste0(strrep("ü", 100), ".json")); writeLines("[1,", f)
e <- t(json_parse_file(f)); m <- conditionMessage(e); cat(class(e)[1], "| validUTF8:", validUTF8(m), "| nchar(bytes):", nchar(m, "bytes"), "\n"); cat(substr(m, nchar(m)-60, nchar(m)), "\n")
f2 <- file.path(tempdir(), "x%s%d.json"); writeLines("{", f2); print(conditionMessage(t(json_parse_file(f2))))
f3 <- file.path(tempdir(), "unread.json"); writeLines("[1]", f3); Sys.chmod(f3, "000"); e <- t(json_parse_file(f3)); cat(class(e)[1], conditionMessage(e), "\n")
f4 <- file.path(tempdir(), "empty.json"); file.create(f4); e <- t(json_parse_file(f4)); cat(class(e)[1], conditionMessage(e), "\n")
f5 <- file.path(tempdir(), "bom.json"); writeBin(as.raw(c(0xef,0xbb,0xbf, charToRaw('{"a":[1,2]}\n'))), f5); str(json_parse_file(f5))
e <- t(json_parse_file("/dev/null")); cat(class(e)[1], conditionMessage(e), "\n")
ff <- file.path(tempdir(), "fifo"); system(paste("mkfifo", shQuote(ff))); system(paste0("(printf '[1,2,3]' > ", shQuote(ff), ") &")); e <- t(json_parse_file(ff)); cat("fifo:", if (inherits(e,"condition")) paste(class(e)[1], conditionMessage(e)) else deparse(e), "\n")
