f6 <- file.path(tempdir(), "d.json"); writeBin(charToRaw(doc), f6)
for (s in list("preserve","coerce","none")) for (df in c(FALSE,TRUE)) cat(s, df, identical(json_parse(doc, s, df), json_parse(charToRaw(doc), s, df)), identical(json_parse(doc, s, df), json_parse_file(f6, s, df)), identical(json_parse(doc,s,df), json_parse_raw(charToRaw(doc),s,df)), "\n")
cat("== escaped vs literal spelling\n")
a <- json_parse('{"\\u00e9":"\\u00e9\\u002f\\/","a":"\\u0041"}'); b <- json_parse('{"é":"é//","a":"A"}'); print(identical(a,b)); print(Encoding(names(a))); print(Encoding(a[[1]])); print(Encoding(a[[2]]))
print(identical(json_parse(' \t\r\n[ 1 ,\n2 ]\r\n '), json_parse('[1,2]')))
cat("== coerce under hostile options\n")
j <- '[100000, 0.5, 1e15, 1e-5, 123456.7, 0.1, 1e5, 3, "a", 1234567890123456789, 0.30000000000000004, 1e22, true]'
base <- json_parse(j, simplify="coerce"); print(base)
op <- options(OutDec=",", scipen=-5, digits=3); h1 <- json_parse(j, simplify="coerce"); options(op); print(identical(base,h1)); if (!identical(base,h1)) print(h1)
op <- options(scipen=100); h2 <- json_parse(j, simplify="coerce"); options(op); print(identical(base,h2)); if (!identical(base,h2)) print(h2)
